sys_script.script:
(function executeRule(current, previous /*null when async*/) {

    // 1. Find the NSH User (Fallback to hardcoded username as per your logic)
    var nshUserSysId = '';
    var shUser = new GlideRecord('sys_user');
    if (shUser.get('user_name', 'gayatri.bhandge@mindsprint.com')) {
        nshUserSysId = shUser.getUniqueValue();
    }

    if (nshUserSysId) {
        // 2. Fire the Event for the Email Notification
        // Parm1 is the recipient (NSH user), Parm2 is the submitter
        gs.eventQueue('x_birl3_clm.draft.staged', current, nshUserSysId, current.submitted_by);

        // 3. Create the In-App Notification (Bell icon)
        var notifTitle = 'New CRM P1 Draft Staged: ' + current.site_code;
        var totalAskLakhs = (parseFloat(current.desired_limit) / 100000).toFixed(2);
        var notifBody = 'Draft demand details for ' + current.customer_name + ' (' + current.site_code + ') submitted by CRM. Total Ask: ₹' + totalAskLakhs + 'L.';

        var inAppGr = new GlideRecord('sys_notification_in_app_message');
        if (inAppGr.isValid()) {
            inAppGr.initialize();
            inAppGr.setValue('recipient', nshUserSysId);
            inAppGr.setValue('title', notifTitle);
            inAppGr.setValue('body', notifBody);
            inAppGr.setValue('source_record', current.getUniqueValue());
            inAppGr.setValue('source_table', 'x_birl3_clm_p1_crm_site_draft');
            inAppGr.setValue('read', false);
            inAppGr.insert();
        }
    }

})(current, previous);
